&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot; data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;Experience working in a flight development program&lt;/span&gt;&lt;/li&gt;
