&lt;li style=&quot;font-size: 10pt; font-family: arial, helvetica, sans-serif;&quot; data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;85&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Someone with experience programming and operating DMG-MORI machines (NLX, NTX, DMC FD, and DMU series)&lt;span style=&quot;font-size: 10pt;&quot; data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt; &lt;/span&gt;&lt;/li&gt;
