&lt;li style=&quot;font-size: 10pt; font-family: arial, helvetica, sans-serif;&quot; data-section-id=&quot;1roumqy&quot; data-start=&quot;3191&quot; data-end=&quot;3324&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: arial, helvetica, sans-serif;&quot;&gt;Ability to work a flexible schedule based on operational timelines, including extended hours or non-standard shifts when required&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-start=&quot;3326&quot; data-end=&quot;3370&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: arial, helvetica, sans-serif;&quot;&gt;&lt;strong data-start=&quot;3326&quot; data-end=&quot;3370&quot;&gt;Nice to haves but not required:&amp;nbsp;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
