&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;Certified QMS lead auditor (AS9100 preferred)&lt;/span&gt;&lt;/li&gt;
