&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Proficient in whatever languages and tools you love most, and willing to learn new ones&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
