&lt;ul&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Bachelor’s or Master’s degree in Mechanical Engineering, Aerospace Engineering, or a related field&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;7+ years of experience in mechanical design, packaging, or thermal management for aerospace or ruggedized electronic systems&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
