&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;Quality assurance and supply chain to ensure subcontractor compliance and reliability&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;Relativity + Customer Fracture Control Boards to achieve vehicle reuse&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 10pt;&quot;&gt;Leadership to develop technical roadmaps, elevate risks, and overcome roadblocks&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/ul&gt;
