&lt;li style=&quot;font-size: 10pt; font-family: arial, helvetica, sans-serif;&quot; data-leveltext=&quot;-&quot; data-font=&quot;Calibri&quot; data-listid=&quot;20&quot; data-list-defn-props=&quot;{&amp;quot;335551671&amp;quot;:45,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Calibri&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;-&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;45&quot; data-aria-level=&quot;1&quot;&gt;&lt;span style=&quot;font-size: 10pt; font-family: arial, helvetica, sans-serif;&quot;&gt;Perform in process inspections using hand tools such as micrometers, calipers, and pin gauges &lt;/span&gt;&lt;/li&gt;
